#!/usr/bin/env python3
"""Print the next order id (ORD-XXXX) to stdout."""

import sys
from pathlib import Path


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base-36 string of the given width."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return chars[0] * width
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    # Pad to width
    while len(result) < width:
        result.append(chars[0])
    return "".join(reversed(result))


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    return int(s, 36)


def main() -> None:
    ids_path = Path("ids.txt")
    if not ids_path.exists():
        print("ORD-" + base36_encode(0), file=sys.stdout)
        return

    lines = [line.strip() for line in ids_path.read_text().splitlines() if line.strip()]
    if not lines:
        print("ORD-" + base36_encode(0), file=sys.stdout)
        return

    # Last non-empty line is the most recent id
    last_id = lines[-1]
    suffix = last_id.removeprefix("ORD-")

    next_num = base36_decode(suffix) + 1
    print("ORD-" + base36_encode(next_num))


if __name__ == "__main__":
    main()

