#!/usr/bin/env python3
"""Read ids.txt (one order id per line, most recent last) and print the next id."""

import string


CHARSET = string.digits + string.ascii_uppercase  # 0-9 then A-Z


def to_base36(n: int, width: int = 4) -> str:
    """Convert integer to zero-padded base-36 string of given width."""
    digits = []
    for _ in range(width):
        digits.append(CHARSET[n % 36])
        n //= 36
    return ''.join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a base-36 string to integer."""
    n = 0
    for ch in s:
        n = n * 36 + CHARSET.index(ch)
    return n


def main() -> None:
    import sys

    try:
        with open("ids.txt") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("ORD-" + to_base36(0), flush=True)
        return

    # Find the last non-empty line containing an order id.
    last_id = None
    for line in reversed(lines):
        stripped = line.strip()
        if stripped.startswith("ORD-") and len(stripped) == 8:
            last_id = stripped
            break

    if last_id is None:
        print("ORD-" + to_base36(0), flush=True)
        return

    suffix = last_id[4:]  # e.g. "243G"
    next_val = from_base36(suffix) + 1
    print("ORD-" + to_base36(next_val), flush=True)


if __name__ == "__main__":
    main()

