#!/usr/bin/env python3
"""Build manifest.json: map each file under release/ to its SHA-256 hex digest."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_PATH = "manifest.json"
REPO_ROOT = os.path.dirname(os.path.abspath(__file__))


def sha256_hex(filepath: str) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main():
    os.chdir(REPO_ROOT)
    manifest = {}

    for root, _dirs, files in os.walk(RELEASE_DIR):
        for name in files:
            full_path = os.path.join(root, name)
            rel_path = os.path.relpath(full_path, REPO_ROOT)
            manifest[rel_path] = sha256_hex(full_path)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Written {MANIFEST_PATH} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

