#!/usr/bin/env python3
"""Print the file names under reports/, one per line, in report order."""

from pathlib import Path


def report_key(path: Path) -> int:
    """Extract the numeric report number from the filename."""
    stem = path.stem  # e.g., "report-1"
    return int(stem.split("-", 1)[1])


def main() -> None:
    reports_dir = Path("reports")
    # List all files in reports/, filter for the report-<n>.txt pattern,
    # sort by the numeric key, and print each filename.
    files = [
        f
        for f in reports_dir.iterdir()
        if f.is_file() and f.suffix == ".txt" and f.stem.startswith("report-")
    ]
    files.sort(key=report_key)
    for f in files:
        print(f.name)


if __name__ == "__main__":
    main()

