import sys
from datetime import datetime, timezone, timedelta


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff_dt = datetime.fromtimestamp(as_of - 7 * 86400, tz=timezone.utc)

    with open("app.log", "r") as f:
        lines = f.readlines()

    old_entries = []
    keep_entries = []

    for line in lines:
        stripped = line.rstrip("\n")
        if len(stripped) < 19 or stripped[10] != " " or stripped[13] != ":" or stripped[16] != ":":
            # Line doesn't start with a valid timestamp; keep it in app.log
            keep_entries.append(stripped)
            continue

        ts_str = stripped[:19]
        try:
            entry_dt = datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        except ValueError:
            keep_entries.append(stripped)
            continue

        if entry_dt < cutoff_dt:
            old_entries.append(stripped)
        else:
            keep_entries.append(stripped)

    if old_entries:
        with open("archive.log", "a") as f:
            for entry in old_entries:
                f.write(entry + "\n")

    with open("app.log", "w") as f:
        for entry in keep_entries:
            f.write(entry + "\n")


if __name__ == "__main__":
    main()

