#!/usr/bin/env python3
import sys
from datetime import datetime, timezone

def parse_timestamp(line):
    """Extract the timestamp from a log line. Returns a datetime or None."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt.timestamp() - 7 * 24 * 60 * 60
    cutoff_dt = datetime.fromtimestamp(cutoff, tz=timezone.utc)

    app_log_path = "app.log"
    archive_log_path = "archive.log"

    # Read all lines from app.log
    with open(app_log_path, "r") as f:
        lines = f.readlines()

    keep_lines = []
    archive_lines = []

    for line in lines:
        # Keep empty lines in place? The spec says "every entry" - let's treat blank lines as we find them
        # If it's an empty line, keep it in app.log (it's not an entry with a timestamp)
        ts = parse_timestamp(line)
        if ts is None:
            keep_lines.append(line)
        elif ts.timestamp() < cutoff:
            archive_lines.append(line)
        else:
            keep_lines.append(line)

    # Append archive lines to archive.log
    if archive_lines:
        with open(archive_log_path, "a") as f:
            f.writelines(archive_lines)

    # Rewrite app.log with kept lines
    with open(app_log_path, "w") as f:
        f.writelines(keep_lines)

if __name__ == "__main__":
    main()

